:root{--bg:#f3f1ee;--panel:#fff;--ink:#17171c;--mute:#6c6a73;--line:#e1ddd8;--accent:#0f9d8a;--accent-ink:#fff;--yes:#16a34a;--yes-bg:#dcf5e5;--no:#d62f4b;--no-bg:#fde3e8}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#121216;--panel:#1c1c22;--ink:#f2f0ed;--mute:#9b98a3;--line:#2e2e36;--accent:#4fe3cc;--accent-ink:#06201b;--yes:#4ade80;--yes-bg:#12301e;--no:#ff6b84;--no-bg:#3a141d;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#121216;--panel:#1c1c22;--ink:#f2f0ed;--mute:#9b98a3;--line:#2e2e36;--accent:#4fe3cc;--accent-ink:#06201b;--yes:#4ade80;--yes-bg:#12301e;--no:#ff6b84;--no-bg:#3a141d;color-scheme:dark}
*{box-sizing:border-box}
body{background:var(--bg);color:var(--ink);font:400 14px/1.45 Inter,system-ui,sans-serif;padding-inline:max(16px,env(safe-area-inset-left,0px)) max(16px,env(safe-area-inset-right,0px));padding-block:28px 40px}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);background:var(--bg);z-index:30}
.wrap{max-width:1240px;margin:0 auto}
h1{font:800 30px/1.1 Archivo,Inter,sans-serif;margin:0 0 8px;letter-spacing:-.02em;text-wrap:balance}
.lead{max-width:66ch;color:var(--mute);margin:0 0 20px}
.bar{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:var(--bg);padding:10px 0;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:10px 16px;align-items:center;margin-bottom:22px}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:999px;padding:6px 12px;font:600 12px Inter,sans-serif;cursor:pointer}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.chip:focus-visible,.vb:focus-visible,.copy:focus-visible,.stage:focus-visible,textarea:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.count{margin-left:auto;font-size:12px;color:var(--mute);font-variant-numeric:tabular-nums}
.copy{background:var(--accent);color:var(--accent-ink);border:0;border-radius:10px;padding:9px 16px;font:800 13px Inter,sans-serif;cursor:pointer}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(352px,1fr));gap:18px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:14px;display:flex;flex-direction:column;gap:10px;min-width:0}
.card[data-v="1"]{border-color:var(--yes);box-shadow:0 0 0 2px var(--yes-bg)}
.card[data-v="-1"]{opacity:.62}
.card[data-v="-1"] .stage{filter:grayscale(.6)}
.stage{position:relative;width:320px;height:180px;border-radius:14px;overflow:hidden;margin:0 auto;box-shadow:0 6px 18px rgba(0,0,0,.18);cursor:pointer;max-width:100%;isolation:isolate}
.meta{display:flex;flex-direction:column;gap:3px}
.nm{font:800 15px/1.2 Archivo,Inter,sans-serif}
.fr{font:600 10px Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}
.ds{font-size:12.5px;color:var(--mute)}
.votes{display:flex;gap:8px}
.vb{flex:1;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:10px;padding:9px 6px;font:700 13px Inter,sans-serif;cursor:pointer}
.vb.y[aria-pressed="true"]{background:var(--yes);border-color:var(--yes);color:#fff}
.vb.n[aria-pressed="true"]{background:var(--no);border-color:var(--no);color:#fff}
.note{width:100%;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:7px 9px;font:400 12px Inter,sans-serif}
.out{margin-top:30px;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:16px}
.out h2{margin:0 0 6px;font:800 18px Archivo,Inter,sans-serif}
.out p{margin:0 0 10px;color:var(--mute);font-size:13px}
textarea{width:100%;min-height:200px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink);padding:10px;font:12px/1.5 ui-monospace,Menlo,monospace}
.empty{padding:40px 0;color:var(--mute);text-align:center}

/* ===== piezas (sobre su propio fondo; no cambian con el tema) ===== */
.stage{--mint:#66e6d2;--ink2:#111;color:#111;font-family:Archivo,Inter,sans-serif}
.abs{position:absolute}.ly{position:absolute;inset:0;overflow:hidden}
.forest{background:linear-gradient(90deg,#55683a 0,#9aa05a 24%,#c9a45c 40%,#738a48 64%,#4d6338 100%)}
.forest::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 16% 28%,rgba(255,236,170,.6) 0 13px,transparent 14px),radial-gradient(circle at 84% 20%,rgba(255,255,255,.5) 0 16px,transparent 17px),radial-gradient(circle at 72% 62%,rgba(255,220,140,.45) 0 11px,transparent 12px),radial-gradient(circle at 30% 70%,rgba(255,255,255,.3) 0 9px,transparent 10px);filter:blur(4px)}
.pp{position:absolute;left:50%;bottom:0;width:150px;height:150px;transform:translateX(-50%);transform-origin:50% 100%}
.pp .h{position:absolute;left:50%;top:6px;width:50px;height:58px;margin-left:-25px;border-radius:46% 46% 48% 48%;background:#e2b48f}
.pp .h::before{content:"";position:absolute;left:-3px;right:-3px;top:-5px;height:26px;border-radius:50% 50% 30% 30%;background:#241a14}
.pp .h::after{content:"";position:absolute;left:12px;top:26px;width:5px;height:5px;border-radius:50%;background:#2a1a12;box-shadow:19px 0 0 #2a1a12}
.pp .b{position:absolute;left:8px;right:8px;top:70px;bottom:-40px;border-radius:44% 44% 0 0/36% 36% 0 0;background:#2e5694}
.pp .b::before{content:"";position:absolute;left:50%;top:0;width:34px;height:40px;margin-left:-17px;background:#f1f1f1;clip-path:polygon(0 0,100% 0,50% 100%)}
.sb{position:absolute;left:0;right:0;bottom:10px;text-align:center;font:800 16px/1.1 Archivo,Inter,sans-serif;color:#fff;text-shadow:0 2px 6px rgba(0,0,0,.6);padding:0 10px}
.cd{background:#fff;border-radius:12px;box-shadow:0 8px 20px rgba(0,0,0,.10),0 1px 3px rgba(0,0,0,.10)}
.mt{display:inline-block;background:var(--mint);color:#0b1f1c;font:900 12px/1 Archivo,Inter,sans-serif;text-transform:uppercase;border-radius:6px;padding:6px 9px;letter-spacing:.01em;white-space:nowrap}
.hv{font-family:Archivo,Inter,sans-serif;font-weight:900;letter-spacing:-.02em;line-height:1}
.cap{font:900 7px/1 Archivo,Inter,sans-serif;text-transform:uppercase;letter-spacing:.03em;color:#555}
.phn{position:absolute;border-radius:14px;background:#0e0e10;padding:3px;box-shadow:0 8px 18px rgba(0,0,0,.28)}
.phn .sc2{position:relative;width:100%;height:100%;border-radius:11px;overflow:hidden;background:#fff}
.tkv{position:absolute;inset:0;background:linear-gradient(170deg,#8aa062,#3d4c2e 70%,#26301d)}
.tkv::before{content:"";position:absolute;left:28%;bottom:0;width:44%;height:42%;border-radius:40% 40% 0 0;background:#e9e4dc}
.tkv::after{content:"";position:absolute;left:39%;bottom:38%;width:22%;aspect-ratio:1;border-radius:50%;background:#c79670;box-shadow:0 -3px 0 1px #3a2a20}
.ln{display:block;height:5px;border-radius:3px;background:#dcdce2}
.dots{background-image:radial-gradient(#2a2a30 1px,transparent 1.3px);background-size:4px 4px}
.bg-dots{background-color:#f7f7f7;background-image:radial-gradient(#e0e0e4 1px,transparent 1.2px);background-size:12px 12px}
.ico{position:absolute;display:grid;place-items:center;border-radius:22%;box-shadow:0 3px 8px rgba(0,0,0,.22);font-size:15px}
.cu{position:absolute;filter:drop-shadow(0 2px 2px rgba(0,0,0,.35))}
.wr{position:absolute;left:30px;right:30px;top:74px;height:32px;border-radius:10px;display:flex;align-items:center;gap:7px;padding:0 9px;background:var(--b0);color:var(--c0);box-shadow:0 5px 14px rgba(0,0,0,.12);font:800 10px Archivo,Inter,sans-serif}
.wr small{display:block;font:500 6px Inter;opacity:.6}
.wr em{margin-left:auto;font:900 12px Archivo;font-style:normal;letter-spacing:-.02em}
@property --p{syntax:'<number>';inherits:false;initial-value:0}
@keyframes kPop{from{opacity:0;transform:scale(.4)}60%{opacity:1;transform:scale(1.1)}to{opacity:1;transform:scale(1)}}
@keyframes kUp{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@keyframes kDn{from{opacity:0;transform:translateY(-26px)}to{opacity:1;transform:none}}
@keyframes kLf{from{opacity:0;transform:translateX(-50px)}to{opacity:1;transform:none}}
@keyframes kRt{from{opacity:0;transform:translateX(60px)}to{opacity:1;transform:none}}
@keyframes kFd{from{opacity:0}to{opacity:1}}
@keyframes kOut{to{opacity:0;transform:scale(.85)}}
@keyframes kWin{0%{opacity:0}8%{opacity:1}92%{opacity:1}100%{opacity:0}}
@keyframes kWinP{0%{opacity:0;transform:scale(.7)}9%{opacity:1;transform:scale(1.06)}15%{transform:scale(1)}90%{opacity:1}100%{opacity:0}}
@keyframes kAp{from{opacity:0}to{opacity:1}}
@keyframes kHide{from{opacity:1}to{opacity:0}}
@keyframes kZin{from{transform:scale(1.4)}to{transform:scale(1)}}
@keyframes kPunch{0%{transform:scale(1)}100%{transform:scale(1.22)}}
@keyframes kGrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes kGrowY{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@keyframes kDraw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@keyframes kMv{from{transform:translate(var(--x0,0),var(--y0,0)) scale(var(--s0,1))}to{transform:translate(var(--x1,0),var(--y1,0)) scale(var(--s1,1))}}
@keyframes kHop{0%{opacity:0;transform:translateY(-34px) scale(.7)}45%{opacity:1;transform:translateY(0) scale(1.06)}62%{transform:translateY(-10px)}80%{transform:translateY(0)}92%{transform:translateY(-3px)}100%{transform:none;opacity:1}}
@keyframes kBlurIn{from{opacity:0;filter:blur(8px);transform:translateY(8px)}to{opacity:1;filter:none;transform:none}}
@keyframes kBlurOut{to{opacity:0;filter:blur(10px)}}
@keyframes kBlur1{from{filter:blur(8px)}to{filter:blur(0)}}
@keyframes kWh{from{transform:translateY(var(--y0)) scale(var(--s0));opacity:var(--o0)}to{transform:translateY(var(--y1)) scale(var(--s1));opacity:var(--o1)}}
@keyframes kWh2{from{transform:translateY(var(--y1)) scale(var(--s1));opacity:var(--o1)}to{transform:translateY(var(--y2)) scale(var(--s2));opacity:var(--o2)}}
@keyframes kWc{from{background:var(--b0);color:var(--c0)}to{background:var(--b1);color:var(--c1)}}
@keyframes kWc2{from{background:var(--b1);color:var(--c1)}to{background:var(--b2);color:var(--c2)}}
@keyframes kSlideL{to{transform:translateX(-120%)}}
@keyframes kSlideR{from{transform:translateX(120%)}to{transform:none}}
@keyframes kType{from{width:0}to{width:var(--w,90px)}}
@keyframes kFlash{0%{opacity:0}35%{opacity:1}100%{opacity:0}}
@keyframes kSel{from{background:#fff}to{background:var(--c,#2f5bff)}}
@keyframes kHalo{0%{box-shadow:0 0 0 0 rgba(102,230,210,.9)}100%{box-shadow:0 0 0 14px rgba(102,230,210,0)}}
@keyframes kPress{0%{transform:scale(1)}50%{transform:scale(.8)}100%{transform:scale(1)}}
@keyframes kClipR{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0)}}
@keyframes kClipD{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
@keyframes kHighl{from{background-size:0 100%}to{background-size:100% 100%}}
@keyframes kPan{from{transform:translateX(0)}to{transform:translateX(var(--dx,-160px))}}
@keyframes kStripe{from{background-position:0 0}to{background-position:28px 0}}
@keyframes kDotsBg{from{background-position:0 0}to{background-position:12px 12px}}
@keyframes kSlot{from{transform:translateX(0)}to{transform:translateX(-62%)}}
@keyframes kFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
@keyframes kTw{0%,100%{opacity:.25}50%{opacity:1}}
@keyframes kGlow{from{box-shadow:0 0 0 rgba(102,230,210,0)}to{box-shadow:0 0 22px rgba(102,230,210,.85),0 0 0 2px #66e6d2 inset}}
@keyframes kNum{from{opacity:1}to{opacity:1}}
@keyframes kW50{from{width:100%}to{width:50%}}
@keyframes kCircF{from{transform:none;clip-path:circle(280px at 160px 72px)}to{transform:translate(122px,72px) scale(.5);clip-path:circle(52px at 160px 72px)}}
@keyframes kCircC{from{transform:none;clip-path:circle(52px at 160px 72px)}to{transform:translate(122px,72px) scale(.5);clip-path:circle(52px at 160px 72px)}}
@keyframes kOp1{to{opacity:.4;transform:scale(.92)}}
@keyframes kOp2{from{opacity:.4;transform:scale(.92)}to{opacity:1;transform:scale(1)}}
@keyframes kOp3{to{opacity:.4;transform:scale(.94)}}
@keyframes kBig{to{transform:scale(1.18)}}
@keyframes kOff{from{offset-distance:0%}to{offset-distance:100%}}
@keyframes kBlurFast{from{filter:blur(7px)}to{filter:blur(0)}}
@keyframes kGradMove{from{background-position:0 0}to{background-position:100% 100%}}
@media (prefers-reduced-motion:reduce){.stage *{animation-duration:.01s!important;animation-delay:0s!important;animation-iteration-count:1!important}}
@media (max-width:520px){.grid{grid-template-columns:1fr}.count{margin-left:0;width:100%}}

