@keyframes kCircC{from{transform:none;clip-path:circle(52px at 160px 72px)}to{transform:translate(122px,72px) scale(.5);clip-path:circle(52px at 160px 72px)}}
@keyframes kOp1{to{opacity:.4;transform:scale(.92)}}
@keyframes kOp2{from{opacity:.4;transform:scale(.92)}to{opacity:1;transform:scale(1)}}
@keyframes kOp3{to{opacity:.4;transform:scale(.94)}}
@keyframes kBig{to{transform:scale(1.18)}}
@keyframes kOff{from{offset-distance:0%}to{offset-distance:100%}}
@keyframes kBlurFast{from{filter:blur(7px)}to{filter:blur(0)}}
@keyframes kGradMove{from{background-position:0 0}to{background-position:100% 100%}}
.pc{display:inline-block;background:#ffc08a;color:#2a1405;font:900 11px/1 Archivo,Inter,sans-serif;text-transform:uppercase;border-radius:6px;padding:6px 9px;white-space:nowrap}
.hlp{background:linear-gradient(#ffc08a,#ffc08a) 0 100%/0 100% no-repeat;animation:kHighl .5s 1s both;padding:0 3px}
.ring{width:84px;height:84px;border-radius:50%;background:conic-gradient(#ff9f5a calc(var(--p)*1%),#ececf0 0);-webkit-mask:radial-gradient(circle,transparent 58%,#000 59%);mask:radial-gradient(circle,transparent 58%,#000 59%)}
@keyframes kFlip3{from{transform:rotateY(0)}to{transform:rotateY(180deg)}}
@keyframes kShrinkCard{from{transform:none;clip-path:inset(0 round 0)}to{transform:translate(-92px,0) scale(.56);clip-path:inset(0 round 26px)}}
@keyframes kRingFill{to{--p:72}}
@keyframes kSpin{to{transform:rotate(360deg)}}
@keyframes kSpinR{to{transform:rotate(-360deg)}}
@keyframes kRing{0%{transform:scale(.8);opacity:.8}100%{transform:scale(2.2);opacity:0}}
@keyframes kScrollY{from{transform:translateY(0)}to{transform:translateY(-190px)}}
@keyframes kRotIn{from{transform:perspective(500px) rotateY(-75deg);opacity:0}to{transform:perspective(500px) rotateY(0);opacity:1}}
@keyframes kMorph{from{left:138px;top:68px;width:44px;height:44px;border-radius:12px}to{left:56px;top:40px;width:208px;height:100px;border-radius:14px}}
@keyframes kBord{from{box-shadow:0 0 0 0 transparent}to{box-shadow:0 0 0 3px #ffb27a}}
@keyframes kWx{from{transform:translateX(var(--y0)) scale(var(--s0));opacity:var(--o0)}to{transform:translateX(var(--y1)) scale(var(--s1));opacity:var(--o1)}}
@keyframes kWx2{from{transform:translateX(var(--y1)) scale(var(--s1));opacity:var(--o1)}to{transform:translateX(var(--y2)) scale(var(--s2));opacity:var(--o2)}}
@keyframes kPeachC{to{color:#ffc08a}}
@keyframes kStrike{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes kPeachBg{to{background:#ffc08a;border-color:#ffc08a}}
@keyframes kKnob2{to{transform:translateX(14px)}}
@keyframes kStar{from{opacity:.2;transform:scale(.5)}to{opacity:1;transform:scale(1)}}
@keyframes kWinL{0%{opacity:0;transform:translateX(-60px)}10%{opacity:1;transform:none}90%{opacity:1}100%{opacity:0}}
@keyframes kMv2{from{transform:translate(0,-44px)}to{transform:translate(0,-88px)}}
@keyframes kPeachC2{to{color:#aaa;text-decoration:line-through}}
@keyframes kNoti{0%{transform:translateY(-70px);opacity:0}55%{transform:translateY(6px);opacity:1}75%{transform:translateY(-2px)}100%{transform:none;opacity:1}}
@keyframes kFly{to{transform:translateX(200px) rotate(10deg);opacity:0}}
@keyframes kSweep2{from{left:-120px}to{left:340px}}
@keyframes kSelW2{to{background:#fff}}
@keyframes kMarq{from{transform:translateX(0)}to{transform:translateX(-50%)}}
@keyframes kRip{0%{transform:scale(.3);opacity:.7}100%{transform:scale(2.4);opacity:0}}
@keyframes kSlotY{0%,22%{transform:translateY(0)}30%,52%{transform:translateY(-28px)}60%,100%{transform:translateY(-56px)}}
@keyframes kBarW{from{width:0}to{width:var(--w,80%)}}
@keyframes kHeat{from{opacity:0;transform:scale(.4)}to{opacity:1;transform:scale(1)}}
@keyframes kFan3{from{opacity:0;transform:translateY(40px) rotate(0)}to{opacity:1;transform:rotate(var(--r))}}
@keyframes kGrowH{from{height:0}to{height:60px}}
@keyframes kPeachG{to{background:#34c759}}
@keyframes kBlink{50%{opacity:.15}}
@keyframes kStamp{0%{opacity:0;transform:scale(2.2) rotate(-12deg)}70%{opacity:1;transform:scale(.92)}100%{opacity:1;transform:scale(1)}}
@keyframes kSlideL{to{transform:translateX(-100%)}}
@media (prefers-reduced-motion:reduce){.stage *{animation-duration:.01s!important;animation-delay:0s!important;animation-iteration-count:1!important}}
@media (max-width:520px){.grid{grid-template-columns:1fr}.count{margin-left:0;width:100%}}
